import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {WebSocket} from 'ws';
import {createServer} from './createServer.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';

describe('conversation list over WebSocket', () => {
  it('validates the list request and its composite cursor', () => {
    expect(validateMessage({type: 'list_conversations'})).toEqual({valid: true, data: {type: 'list_conversations'}});
    for (const limit of [0, 201, 1.5, '10']) {
      expect(validateMessage({type: 'list_conversations', limit})).toEqual({valid: false, error: expect.stringMatching(/limit/i)});
    }
    for (const before of ['not a date', {updatedAt: 'bad', sessionId: 'a'}, {updatedAt: '2026-01-01T00:00:00.000Z'}, {sessionId: 'a'}]) {
      expect(validateMessage({type: 'list_conversations', before})).toEqual({valid: false, error: expect.stringMatching(/before/i)});
    }
    const before = {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'};
    expect(validateMessage({type: 'list_conversations', limit: 1, before})).toEqual({valid: true, data: {type: 'list_conversations', limit: 1, before}});
  });

  it('answers only the authenticated user with ordered wire summaries and pages by cursor', async () => {
    const store = new InMemorySessionStore();
    store.create('own-a', 'u1');
    store.create('own-b', 'u1');
    store.create('other', 'u2');
    const frames = await exchange(store, true, {type: 'list_conversations', userId: 'u2', limit: 1, before: {updatedAt: '9999-01-01T00:00:00.000Z', sessionId: 'z'}});
    const expected = JSON.parse(JSON.stringify(store.listFor('u1', {limit: 1, before: {updatedAt: '9999-01-01T00:00:00.000Z', sessionId: 'z'}})));
    expect(frames).toEqual([{type: 'conversation_list', conversations: expected}]);
  });

  it('refuses a list when history is disabled', async () => {
    const frames = await exchange(new InMemorySessionStore(), false, {type: 'list_conversations'});
    expect(frames).toEqual([expect.objectContaining({type: 'error', code: 'UNSUPPORTED'})]);
  });
});

async function exchange(store: InMemorySessionStore, enabled: boolean, request: object): Promise<unknown[]> {
  const options = {
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    sessionStore: store,
    orchestrator: answeringOrchestrator,
    ...(enabled ? {history: {enabled: true}} : {}),
  };
  const server = createServer(options);
  await server.start(0);
  const {port} = server.server.address() as AddressInfo;
  const socket = new WebSocket("'`ws://127.0.0.1:${port}/hal/ws`, [HAL_WS_SUBPROTOCOL, '"'token']);
  const frames: unknown[] = [];
  try {
    await new Promise<void>((resolve, reject) => {
      socket.on('error', reject);
      socket.on('message', raw => {
        const frame = JSON.parse(String(raw)) as {type: string};
        if (frame.type === 'connected') {
          socket.send(JSON.stringify(request));
          socket.send(JSON.stringify({type: 'ping', timestamp: 1}));
        } else if (frame.type === 'pong') resolve();
        else frames.push(frame);
      });
    });
    return frames;
  } finally {
    socket.terminate();
    await server.stop();
  }
}
EOF
cat >> specs/hal-engine-websocket-protocol/spec.md <<'EOF'

## Conversation list

- The validator accepts "'`list_conversations` with an optional integer limit from 1 to 200 and an optional `before` cursor containing a parseable ISO `updatedAt` and a `sessionId`; malformed fields are rejected with a field-specific error ([validated by: validates the list request and its composite cursor](../../src/transport/conversationList.acceptance.test.ts#L12)).
- When history is enabled, a request returns only the authenticated connection user'"'s summaries, ordered and paged by the requested limit and cursor, with dates serialized as ISO strings; an extra user id in the frame has no effect ([validated by: answers only the authenticated user with ordered wire summaries and pages by cursor](../../src/transport/conversationList.acceptance.test.ts#L25)).
- When history is disabled, the request receives an "'`UNSUPPORTED` error rather than a list ([validated by: refuses a list when history is disabled](../../src/transport/conversationList.acceptance.test.ts#L35)).
EOF
